WF.updateCheck=function(){const LAST_SEEN_KEY="wf_checklist_last_seen_version",FILE_NAME="version.js",FETCH_TIMEOUT_MS=5e3,TOAST_KEY="wf-update-available";let checkIntervalId=null,currentRemoteVersion=null;const updateToggle=document.getElementById("btn-update-toggle");updateToggle&&updateToggle.addEventListener("click",(()=>showUpdateAvailable()));let hasSettled=!1;function isOffline(){return!1===navigator.onLine}function isLocalCopy(){return"file:"===window.location.protocol}function updateMessage(){return isLocalCopy()?"A new version is available, download it from":"A new version is available, refresh this page (Ctrl+F5) to get it."}function updateLink(){return isLocalCopy()?{href:WF.PROJECT_URL,text:"GitHub"}:null}function markVersionAsSeen(){if(currentRemoteVersion)try{localStorage.setItem(LAST_SEEN_KEY,String(currentRemoteVersion))}catch(err){console.warn("Unable to persist last seen version.",err)}}function showUpdateAvailable(){WF.toast.show(updateMessage(),{key:TOAST_KEY,link:updateLink(),timeoutMs:0,type:"info",onClose:markVersionAsSeen})}function stopPeriodicCheck(){checkIntervalId&&(clearInterval(checkIntervalId),checkIntervalId=null)}async function check(){const localVersion=Number(WF.WCT_VERSION);if(!localVersion||Number.isNaN(localVersion))return!0;if(isOffline())return!1;try{const response=await fetch(`${WF.PROJECT_URL}js/${FILE_NAME}`,{cache:"no-store",signal:AbortSignal.timeout(FETCH_TIMEOUT_MS)});if(!response.ok)return!1;const match=(await response.text()).match(/WF\.WCT_VERSION\s*=\s*(\d+)/);if(!match)return!1;const remoteVersion=Number(match[1]);return!!(Number.isNaN(remoteVersion)||remoteVersion<=localVersion)||(currentRemoteVersion=remoteVersion,function(){const raw=localStorage.getItem(LAST_SEEN_KEY);if(null===raw)return 0;const parsed=Number(raw);return Number.isNaN(parsed)?0:parsed}()>=remoteVersion?(stopPeriodicCheck(),!0):(function(){const notice=document.getElementById("update-available-notice");if(notice){notice.textContent=updateMessage();const link=updateLink();if(link){notice.appendChild(document.createTextNode(" "));const anchor=document.createElement("a");anchor.href=link.href,anchor.textContent=link.text,anchor.target="_blank",anchor.rel="noopener noreferrer",notice.appendChild(anchor)}notice.classList.remove("hidden")}updateToggle&&updateToggle.classList.remove("hidden")}(),showUpdateAvailable(),stopPeriodicCheck(),!0))}catch(err){return console.warn("Error while fetching remote version.",err),!1}}async function runCheck(){const settled=await check();return settled&&(hasSettled=!0,stopPeriodicCheck()),settled}return{check:check,init:function(){window.addEventListener("offline",(()=>{WF.toast.show("You are now offline, it should work as usual.",{type:"info"})})),window.addEventListener("online",(async()=>{WF.toast.show("You are back online.",{type:"info"}),isOffline()||await runCheck()})),isOffline()?WF.toast.show("You are offline, it should work as usual.",{type:"info"}):runCheck().then((settled=>{settled||(checkIntervalId=setInterval(runCheck,6e4))}))}}}(),document.addEventListener("DOMContentLoaded",(()=>{WF.updateCheck.init()}));